from pathlib import Path
import json
from html import escape
ROOT=Path(__file__).resolve().parents[1]
RESOURCES=json.loads((ROOT/'resources/courses.json').read_text())
def tr(lang,en,zh):return zh if lang=='zh' else en
def chapter_mapping(lang,slug):
    unit=next(x for x in RESOURCES['units'] if x['unit']==slug)
    links=' · '.join(f'<a href="{x["url"]}">{escape(x["title"])}</a>' for x in unit['materials'])
    return f'<section class="course-match"><h2>{tr(lang,"Study alongside MIT 6.5840","对照 MIT 6.5840 学习")}</h2><p>{links}</p><p>{escape(unit["practice_goal_"+lang])}</p><pre><code>{escape(unit["original_practice_command"])}</code></pre><p class="demo-small">{tr(lang,"Our runnable exercise is an independent original, not the linked MIT assignment solution. Setup is on the reproduce page; no enrollment, grade or certification is implied.","本 Lab 可运行练习为独立原创，不是所链接 MIT 作业的解答。安装方法见复现页；不代表注册、评分或认证。")}</p><a href="resources.html">{tr(lang,"Search the verified course map","检索已核验课程地图")} →</a></section>'
def resources_page(lang):
    intro=tr(lang,'One focused university course, mapped to seven learning units. The listed public notes and lab descriptions were checked on 2026-11-14. The Spring 2026 schedule still labels itself tentative; we report the pages as published, not a guarantee about every class event.','用一门直接相关的大学课程贯穿七个学习单元。所列公开讲义与作业说明核验于 2026-11-14。Spring 2026 日程页仍标注 tentative；这里确认页面已公开，不替每次课堂活动作保证。')
    cards=''
    for u in RESOURCES['units']:
        links=''.join(f'<li><a href="{m["url"]}">{escape(m["title"])}</a></li>' for m in u['materials'])
        search=escape('MIT Massachusetts Institute of Technology 6.5840 6.824 Spring 2026 '+u['title_en']+' '+u['title_zh']+' '+' '.join(m['title'] for m in u['materials']),quote=True)
        cards+=f'<section class="resource-item" data-resource-unit data-search="{search}"><p class="resource-meta">MIT · 6.5840 · Spring 2026 · {u["unit"][:2]}</p><h3><a href="{u["unit"]}.html">{escape(u["title_"+lang])}</a></h3><ul>{links}</ul><p>{escape(u["practice_goal_"+lang])}</p><pre><code>{escape(u["original_practice_command"])}</code></pre></section>'
    return f'<p class="lede">{tr(lang,"A course map you can act on.","一份能接着动手的课程地图。")}</p><p>{intro}</p><div class="case-brief"><strong>Massachusetts Institute of Technology · 6.5840: Distributed Systems</strong><p>Spring 2026 · <a href="https://pdos.csail.mit.edu/6.824/">Official home</a> · <a href="https://pdos.csail.mit.edu/6.824/schedule.html">Schedule</a> · <a href="https://pdos.csail.mit.edu/6.824/general.html">Policies</a></p><p>{tr(lang,"Prerequisites: 6.1910 (6.004) plus one of 6.1800 (6.033) or 6.1810, or equivalent; substantial programming experience helps.","官方先修：6.1910（6.004），以及 6.1800（6.033）或 6.1810 之一，或同等基础；需要较强编程经验。")}</p></div><p>{tr(lang,"Public reading access is separate from MIT registration, tuition, graded submissions and academic credit. We make no enrollment, pricing or certification promise. Do not publish solutions to MIT labs; this companion contains independent exercises and none of the course solution code.","公开阅读与 MIT 注册、学费、评分提交和学分是不同事项。这里不承诺注册资格、价格或认证。不要公开 MIT 作业解答；本配套项目只提供独立原创练习，不包含原课解答代码。")}</p><p><a href="../resources/courses.json" download>{tr(lang,"Download the structured resource list (JSON)","下载结构化资源清单（JSON）")}</a></p><label for="resource-search">{tr(lang,"Search course, topic, lecture or lab","搜索课程、主题、讲次或作业")}</label><input id="resource-search" class="resource-search" data-resource-search type="search" placeholder="Raft / RPC / 6.5840 / 恢复"><p role="status" data-resource-count></p>{cards}<h2>{tr(lang,"Classic supplements, with their dates","注明年代的经典补充")}</h2><p><a href="https://lamport.azurewebsites.net/pubs/time-clocks.pdf">Lamport, 1978 — Time, Clocks, and the Ordering of Events</a> · <a href="https://research.google/pubs/the-chubby-lock-service-for-loosely-coupled-distributed-systems/">Burrows, 2006 — Chubby</a>.</p><p>{tr(lang,"These supplement causality and sequencers. They are not presented as 2026 discoveries or additional university courses.","它们补充因果与 sequencer，不被包装成 2026 年新成果或另外两门大学课程。")}</p>'
